import{z as A,x as B,o as s,c as p,q as r,j as o,D as n,d as e,s as l,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"混沌工程","description":"","frontmatter":{"title":"混沌工程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chaos-engineering.md","filePath":"cs/chaos-engineering.md","lastUpdated":1791063341000}'),d={name:"cs/chaos-engineering.md"};function m(f,a,h,c,C,D){const i=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=r('<h1 id="混沌工程" tabindex="-1">混沌工程 <a class="header-anchor" href="#混沌工程" aria-label="Permalink to &quot;混沌工程&quot;">​</a></h1><div class="epigraph"><p>在生产（或逼近生产）里有控制地注入故障，用实验检验稳态假设。不是随机砸机器，也不是单元测试的别名。</p><footer>—— 据 Principles of Chaos Engineering；Netflix Chaos Monkey / Simian Army 实践整理</footer></div><p>上一课<a href="/cs/observability-pillars">三支柱</a>给测量。缺口是<strong>假设未验证</strong>：熔断、重试、副本，纸面上抗 \\(f\\) 崩溃。混沌工程把<a href="/cs/failure-models">故障模型</a>变成实验：杀进程、加延迟、丢包、分区。本课钉实验纪律。后课 GFS 是存储系统，不是实验方法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稳态：可测的 SLO，不是「感觉挺好」。<span class="marginnote">术语翻译：「稳态」就是系统健康时的可测量基线，比如「读接口 p99 延迟低于 200 毫秒」；「稳态假设」则是你下的赌注——「就算杀掉一个从库，这条基线也守得住」。它是可证伪的，实验就是要让赌注见真章。</span>假设：杀掉从库，读延迟仍在预算。实验：最小爆炸半径，可回滚，有止损。<span class="marginnote">数字实例：实验前先定死止损线——例如「p99 超过 800 毫秒且持续 60 秒，自动终止注入」。止损动作必须比注入本身更快生效，否则实验就退化成了一场真实事故。</span>观察：用指标与追踪看是否破 SLO。缺口：在开发环境注入与生产拓扑不同，证不了生产假设。Netflix 在生产做是因为副本与自动修复已是规格的一部分。</p><p>与 Jepsen：Jepsen 是线性一致等规格的对抗测试，偏正确性；混沌偏可用性与恢复。可互补。Jepsen 课在数据库补层，本课不重写。</p><p><span class="marginnote">Principles of Chaos 是社区文件。Chaos Monkey 随机关 VM，后续有延迟、分区等更细的猴子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先游戏日（game day）小流量，再自动化。注入种类对齐故障类：崩溃停、漏发（丢包）、时钟跳变、依赖 5xx。禁止无观察的注入。爆炸半径：一实例 → 一区 → 停。</p>',9)),(s(),o(t,null,{default:n(()=>[l(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HYP%5B%22%E7%A8%B3%E6%80%81%E5%81%87%E8%AE%BE%22%5D%20--%3E%20INJ%5B%22%E6%B3%A8%E5%85%A5%E6%95%85%E9%9A%9C%22%5D%0A%20%20INJ%20--%3E%20MEAS%5B%22%E4%B8%89%E6%94%AF%E6%9F%B1%E6%B5%8B%E9%87%8F%22%5D%0A%20%20MEAS%20--%3E%20OK%7B%22SLO%20%E4%BB%8D%E7%AB%8B%3F%22%7D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20FIX%5B%22%E4%BF%AE%E7%B3%BB%E7%BB%9F%E6%88%96%E4%BF%AE%E5%81%87%E8%AE%BE%22%5D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20CONF%5B%22%E6%8F%90%E9%AB%98%E4%BF%A1%E5%BF%83%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要在无熔断无重试预算时对生产做全分区——那是事故，不是实验。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("与"),E("a",{href:"/cs/flp-impossibility"},"FLP"),e("：实验不能「证伪」定理；只能检验你们的部分同步与检测器在真实延迟下是否活着。与脑裂：分区实验是最值钱的一类，必须有 fencing 观察（是否双写）。")],-1)),a[6]||(a[6]=E("p",null,"注入种类各有自己的靶子——哪类故障戳的是哪个假设：",-1)),(s(),o(t,null,{default:n(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20KILL%5B%22%E5%B4%A9%E6%BA%83%E5%81%9C%3A%20%E6%9D%80%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20T1%5B%22%E6%A3%80%E9%AA%8C%E5%89%AF%E6%9C%AC%E6%8E%A5%E7%AE%A1%E4%B8%8E%E8%87%AA%E5%8A%A8%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20DROP%5B%22%E6%BC%8F%E5%8F%91%3A%20%E4%B8%A2%E5%8C%85%E4%B8%8E%E5%BB%B6%E8%BF%9F%22%5D%20--%3E%20T2%5B%22%E6%A3%80%E9%AA%8C%E8%B6%85%E6%97%B6%E3%80%81%E9%87%8D%E8%AF%95%E4%B8%8E%E7%86%94%E6%96%AD%E9%A2%84%E7%AE%97%22%5D%0A%20%20CLK%5B%22%E6%97%B6%E9%92%9F%E8%B7%B3%E5%8F%98%22%5D%20--%3E%20T3%5B%22%E6%A3%80%E9%AA%8C%20TTL%20%E4%B8%8E%E9%A1%BA%E5%BA%8F%E5%81%87%E8%AE%BE%22%5D%0A%20%20DEP%5B%22%E4%BE%9D%E8%B5%96%205xx%22%5D%20--%3E%20T4%5B%22%E6%A3%80%E9%AA%8C%E9%99%8D%E7%BA%A7%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PART%5B%22%E7%BD%91%E7%BB%9C%E5%88%86%E5%8C%BA%22%5D%20--%3E%20T5%5B%22%E6%A3%80%E9%AA%8C%E8%84%91%E8%A3%82%E4%B8%8E%20fencing%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>本课不把随机杀进程当覆盖拜占庭。撒谎故障要恶意客户端，不是 Chaos Monkey 默认。</p><p>安全：权限与审计，防止实验框架成为攻击面。本课点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写所有工具名。不引入形式化模型检测（TLA+ 在课序末）。后课默认：容错声明要有对应注入与 SLO；存储课讲 GFS 如何把崩溃当常态设计，不是如何做猴子。</p><p>实验提高的是对<strong>这个拓扑、这份配置</strong>的信心。换一次超时，假设要重测。<span class="marginnote">直觉类比：混沌实验像打疫苗——主动注入一小剂可控的「病原」（故障），赌的是系统的免疫系统（副本、熔断、降级）能在观察下扛过去。区别在于疫苗打完终身免疫，而系统换个配置就要重新接种。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>混沌：有假设、有测量、有半径的故障注入。</li><li>对齐故障类；分区实验看是否脑裂。</li><li>不能替代 Jepsen 式正确性对抗，也不能推翻 FLP。</li><li>出处：Principles of Chaos；Netflix Simian Army。</li></ul>',7))])}const u=A(d,[["render",m]]);export{g as __pageData,u as default};
